import{_ as i,P as s,d as o,e as r,x as t,q as n}from"./chunks/framework.BRr8VP3a.js";const g=JSON.parse('{"title":"Part 2 Boundaries and Methods","description":"","frontmatter":{"title":"Part 2 Boundaries and Methods","xkChars":4,"xkWords":6553,"xkLessons":{"2.1.1":{"title":"Domain evidence keeps its own standing","lead":"A framework-specific eligibility rule must not erase a conclusion supported by another appropriate method.","explanation":["The section separates a real object or domain finding from eligibility for a particular formal instance in this framework. A document can establish that an organization was registered; observations can establish what a service did. These facts do not wait for a G1 grouping-gain test.","G1 instead asks whether a declared grouping improves a specified explanatory or forecasting task relative to the matched null model and other conditions. An unsupported grouping-gain claim therefore leaves the independently grounded object facts intact.","The same discipline applies to learning, injury, or a historical effect. Existing research retains the support its actual design provides. It must not be silently upgraded into a pre-registered framework test, but neither should it be dismissed because it lacks the framework’s identifiers."],"distinctions":[{"leftTitle":"Object fact","leftText":"Supported by appropriate documentary or observational evidence.","rightTitle":"Grouping gain","rightText":"A task-relative comparison with its own instance conditions."}],"teachingExamples":[{"title":"A registered team and a predictive grouping","text":"Suppose reliable records show a team exists. Grouping its members together fails to improve a particular forecast over a simpler baseline. The team’s documented existence remains supported; the forecast grouping gain does not.","assumptions":"Hypothetical example; the baseline and target are assumed to be appropriately specified.","boundary":"It does not establish any real team or measured gain."}],"boundaries":["Do not retroactively label existing studies pre-registered G-instances.","A source’s existence is not enough: its actual method must support the particular claim."],"questionAnswers":[{"question":"Does missing G1 support make the organization nonexistent?","answer":"No. It limits the grouping-gain claim. Object facts and each domain conclusion retain their independent evidential bases.","basis":"Theory v2, §2.1.1, with the distinctions explained above."}],"caseLinks":[{"title":"London taxi trainees: distinct learning outcomes","href":"/en/cases/london-taxi-learning"}],"sourceRefs":[{"section":"2.1.1","startLine":251,"endLine":258}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-1-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.1.1; English reading edition, lines 251–258","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.4.2":{"title":"Average effects do not automatically join into one chain","lead":"The units responding to the first link may be different from those responding to the second.","explanation":["A causal chain needs more than separately positive averages. The question concerns the joint response of the same cases under compatible conditions. Timing, common support, capacity, and the final outcome must also match the proposed composition.","The source’s two-type construction makes the missing correspondence visible. One type changes its mediator in response to treatment but has no outcome response to that mediator. The other type has an outcome response but no treatment-induced mediator change. Each average link is positive, while the whole-chain effect is zero.","This counterexample does not withdraw a total effect independently identified by a valid design. A total effect, a specific mediator, and a composed chain are different estimands; knowing one does not require pretending to know all the others."],"distinctions":[{"leftTitle":"Separate link averages","leftText":"May describe effects across different responding units.","rightTitle":"Whole-chain effect","rightText":"Requires compatible joint response and the endpoint of the same chain."}],"teachingExamples":[{"title":"Two equally weighted types","text":"For s∈{0,1}, set m(a)=a(1−s) and y(a,m)=sm. Each link’s average effect is 1/2, but y(a,m(a)) is always zero. Multiplying the averages gives a false 1/4.","assumptions":"The two types have equal weight and exactly the stipulated response functions.","boundary":"A formal counterexample, not a real population estimate."}],"boundaries":["The counterexample rules out unconditional multiplication; it does not show all causal composition is impossible."],"questionAnswers":[{"question":"Must a well-identified total effect be rejected if one mediator remains unknown?","answer":"No. Preserve the supported total effect and leave the unresolved mechanism separate.","basis":"Theory v2, §2.4.2, with the distinctions explained above."}],"caseLinks":[{"title":"Two effective links can fail as a whole","href":"/en/concepts/chain"}],"sourceRefs":[{"section":"2.4.2","startLine":333,"endLine":340}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-4-2","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.4.2; English reading edition, lines 333–340","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.4.3":{"title":"A valid status and its consequences need different evidence","lead":"Constitutive standing is established under applicable rules; causal effects concern what happens through it.","explanation":["Some relations constitute an office, right, membership, authorization, or promise under the rules of the relevant practice. Their standing is not inferred simply by observing that they produced an effect. A valid right may be obstructed in practice; actual influence can exist without valid authority.","Keep four inquiries visible: whether constitutive conditions hold, how participants understand the arrangement, whether it is implemented, and whether it is normatively justified. Documentary interpretation and causal inquiry may both matter, but answer different questions.","This prevents two opposite errors. Lack of an observed consequence does not automatically cancel an established right. A successful intervention does not retroactively supply a missing mandate or prove that a rule is just."],"distinctions":[{"leftTitle":"Constitutive relation","leftText":"The applicable rules establish a specified standing.","rightTitle":"Causal relation","rightText":"A supported channel explains an actual effect."}],"teachingExamples":[{"title":"An approved entitlement and a delayed payment","text":"Assume a valid decision grants a benefit, but payment has not arrived. The entitlement may already exist; delivery remains incomplete. Whether the arrangement is fair requires a further argument.","assumptions":"The validity of the decision is independently established; no real legal case is asserted.","boundary":"The example does not determine any jurisdiction’s rules or authorize collection."}],"boundaries":["The framework does not invent the constitutive rules of a domain.","Legal validity and normative justification remain distinct."],"questionAnswers":[{"question":"If an unauthorized actor successfully solves a problem, has the success created authorization?","answer":"No. Effectiveness does not supply the applicable constitutive conditions for authority.","basis":"Theory v2, §2.4.3, with the distinctions explained above."}],"caseLinks":[{"title":"Democratic authorization: the scope of an office","href":"/en/cases/democratic-authorization"}],"sourceRefs":[{"section":"2.4.3","startLine":341,"endLine":348}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-4-3","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.4.3; English reading edition, lines 341–348","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"2.14":{"title":"Freeze a test without monopolizing the question","lead":"Preserve the original question and result while allowing a justified new question to be opened.","explanation":["Freezing protects an inquiry against moving its target after the outcome is known. It does not give the original question-setter permanent ownership of the goal, population, losses, or constraints. Affected and excluded positions can identify omissions and challenge the framing.","A reopening request should identify what changes and why. Its handling and reasons remain on record even if it is rejected. A new inquiry preserves the old question, evidence, and result rather than replacing a failure with a newly convenient success.","This matters especially when an apparent constraint is itself a prior decision. Asking who controls a shortage can open a relevant policy question. It cannot change what the original resource-limited test actually found.","State whether the new question replaces, runs parallel to, or refines the old one, and which existing evidence still applies. The analyst may answer both side by side. Actual changes to an institution’s indicators, eligibility, agenda, or resource allocation belong to the procedure with the corresponding authority; an analytical reframing does not itself change those rules."],"distinctions":[{"leftTitle":"Preserve the test","leftText":"Keep its original target, conditions, and outcome.","rightTitle":"Reopen the question","rightText":"State a new framing and preserve the history of the change."}],"teachingExamples":[{"title":"A service target omitted waiting time","text":"Suppose a frozen review measures completed transactions. Users then identify an omitted waiting burden. Keep the transaction result, record the challenge, and assess a new waiting-time question with suitable evidence.","assumptions":"Hypothetical review; transaction counts are assumed accurate.","boundary":"The omission does not automatically prove the original numerical result false."}],"boundaries":["Reopening is not permission for retrospective success claims.","An affected person need not master the framework’s terminology to challenge a question."],"questionAnswers":[{"question":"Is a disappointing outcome alone a reason to redefine success?","answer":"No. A new question needs an explicit reason and its own record; the old outcome is retained.","basis":"Theory v2, §2.14, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"2.14","startLine":453,"endLine":472}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-02#section-2-14","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§2.14; English reading edition, lines 453–472","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-02.md","filePath":"en/theory/part-02.md"}'),c={name:"en/theory/part-02.md"};function l(d,e,h,p,u,m){const a=s("SectionLesson");return o(),r("div",null,[e[0]||(e[0]=t("",1)),n(a,{section:"2.1.1"}),e[1]||(e[1]=t("",1)),n(a,{section:"2.4.2"}),e[2]||(e[2]=t("",1)),n(a,{section:"2.4.3"}),e[3]||(e[3]=t("",1)),n(a,{section:"2.14"}),e[4]||(e[4]=t("",3))])}const b=i(c,[["render",l]]);export{g as __pageData,b as default};
